splice_start.num = splice_end.num = 0;
        splice_start.den = splice_end.den = 0;
        chap_name[0]=0;

        f = gf_fopen(ctx->file_path, "rt");
        while (f) {
                char *l = gf_fgets(szURL, GF_MAX_PATH, f);
                if (!l || (gf_feof(f) && !szURL[0]) ) {
                        if (ctx->floop != 0) {
                                gf_fseek(f, 0, SEEK_SET);
                                //load first line
                                if (last_found) {
                                        if (!ctx->floop) return GF_FALSE;
                                        if (ctx->floop>0) ctx->floop--;
                                        ctx->last_url_crc=0;
                                }
                                last_found = GF_TRUE;
                                lineno=0;
                                continue;
                        }
                        if (ctx->ka && !is_end && !last_found && url_crc) {
                                gf_fseek(f, 0, SEEK_SET);
                                last_found = GF_TRUE;
                                lineno=0;
                                continue;
                        }

                        gf_fclose(f);
                        if (is_end) {
                                ctx->ka = 0;
                        } else if (ctx->ka) {
                                ctx->wait_update_start = gf_sys_clock();
                                ctx->last_file_modif_time = gf_file_modification_time(ctx->file_path);
                        }
                        return GF_FALSE;
                }
                url_crc = 0;

                len = (u32) strlen(szURL);
                //in keep-alive mode, each line shall end with \n, of not consider the file is not yet ready
                if (ctx->ka && !is_end && len && (szURL[len-1]!='\n')) {
                        gf_fclose(f);
                        ctx->wait_update_start = gf_sys_clock();
                        ctx->last_file_modif_time = gf_file_modification_time(ctx->file_path);
                        return GF_FALSE;
                }
                //strip all \r, \n, \t at the end
                while (len && strchr("\n\r\t ", szURL[len-1])) {
                        szURL[len-1] = 0;
                        len--;
                }
                if (!len) continue;

                //comment
                if (szURL[0] == '#') {
                        //ignored line
                        if (szURL[1] == '#')
                                continue;

                        char *args = szURL+1;
                        nb_repeat=0;
                        start=stop=0;
                        do_cat = 0;
                        start_range=end_range=0;
                        if (ctx->pid_props) {
                                gf_free(ctx->pid_props);
                                ctx->pid_props = NULL;
                        }

                        while (args) {
                                char c;
                                Bool skip_first=GF_FALSE;
                                char *sep, *aval = NULL;
                                while (args[0]==' ') args++;

                                sep = strchr(args, ' ');
                                if (strncmp(args, "props", 5))
                                        aval = strchr(args, ',');

                                if (!strncmp(args, "chap=\"", 6)) {
                                        sep = strchr(args+7, '\"');
                                        if (sep) skip_first = GF_TRUE;
                                }

                                if (sep && aval && (aval < sep))
                                        sep = aval;
                                else if (aval)
                                        sep = aval;

                                if (sep) {
                                        c = sep[0];
                                        sep[0] = 0;
                                }
